CREATE TABLE IF NOT EXISTS payroll_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, pay_date date, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_compensation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, effective_from date NOT NULL, currency text NOT NULL DEFAULT 'NGN', base_salary numeric(14,2) NOT NULL DEFAULT 0, housing_allowance numeric(14,2) NOT NULL DEFAULT 0, transport_allowance numeric(14,2) NOT NULL DEFAULT 0, other_allowance numeric(14,2) NOT NULL DEFAULT 0, pension_employee numeric(14,2) NOT NULL DEFAULT 0, tax_withholding numeric(14,2) NOT NULL DEFAULT 0, other_deduction numeric(14,2) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payroll_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_id uuid NOT NULL REFERENCES payroll_periods(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'draft', gross_total numeric(16,2) NOT NULL DEFAULT 0, deductions_total numeric(16,2) NOT NULL DEFAULT 0, net_total numeric(16,2) NOT NULL DEFAULT 0, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payroll_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id uuid NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, gross_pay numeric(14,2) NOT NULL DEFAULT 0, deductions numeric(14,2) NOT NULL DEFAULT 0, net_pay numeric(14,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'calculated', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payroll_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id uuid NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, action text NOT NULL, note text, approved_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_comp_person_effective ON employee_compensation(person_id,effective_from DESC); CREATE INDEX IF NOT EXISTS idx_payroll_period_status ON payroll_periods(status); CREATE INDEX IF NOT EXISTS idx_payroll_item_run ON payroll_items(payroll_run_id);